\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb}

\title{Lecture Notes: Concentration of Martingales}
\author{Dr.~P.~Anand}
\date{Winter Term 2026}

\begin{document}
\maketitle

\section{Setup}
Let $X_1,\dots,X_n$ be a martingale difference sequence with respect to
a filtration $\mathcal{F}_0 \subset \cdots \subset \mathcal{F}_n$, so
that $\mathbb{E}[X_i \mid \mathcal{F}_{i-1}] = 0$ for all $i$. Write
$S_n = \sum_{i \le n} X_i$ for the partial sum. Throughout the notes we
assume bounded increments: $|X_i| \le c_i$ almost surely.

\noindent\textbf{Theorem 1 (Azuma--Hoeffding).}
\emph{For every $t > 0$,
\[
\Pr\!\left( |S_n| \ge t \right) \le
2 \exp\!\left( \frac{-t^2}{2 \sum_{i \le n} c_i^2} \right).
\]}

\noindent\emph{Proof.}
We bound the moment generating function of $S_n$ step by step.
Conditioning on $\mathcal{F}_{n-1}$ and using the convexity of the
exponential, $\mathbb{E}[e^{\lambda X_n} \mid \mathcal{F}_{n-1}] \le
\exp(\lambda^2 c_n^2 / 2)$. Iterating over all steps and applying
Markov's inequality to $e^{\lambda S_n}$ with the optimising $\lambda$
gives the claim.
\hfill$\square$

\noindent\textbf{Lemma 2.}
\emph{If $Y$ is a random variable with $\mathbb{E}[Y] = 0$ and
$a \le Y \le b$ almost surely, then
$\mathbb{E}[e^{\lambda Y}] \le \exp\!\bigl(\lambda^2 (b-a)^2 / 8\bigr)$.}

\noindent\emph{Proof.}
By convexity, $e^{\lambda y} \le \frac{b-y}{b-a} e^{\lambda a} +
\frac{y-a}{b-a} e^{\lambda b}$ for $y \in [a,b]$. Taking expectations
removes the linear term, and the remaining function of $\lambda$ is
bounded by the claimed exponent after taking a logarithm and
estimating the second derivative.
\hfill$\square$

\noindent\textbf{Theorem 3 (Bounded Differences).}
\emph{Let $f$ satisfy the bounded-differences property with constants
$c_i$. Then for every $t > 0$,
\[
\Pr\!\left( |f - \mathbb{E} f| \ge t \right) \le
2 \exp\!\left( \frac{-2t^2}{\sum_{i \le n} c_i^2} \right).
\]}

\noindent\emph{Proof.}
Write $f - \mathbb{E} f$ as the telescoping sum of the Doob martingale
differences $Z_i = \mathbb{E}[f \mid \mathcal{F}_i] -
\mathbb{E}[f \mid \mathcal{F}_{i-1}]$. Each $Z_i$ lies in an interval
of length at most $c_i$, so the exponential bound applies term by
term, and the concentration inequality for the sum follows.
\hfill$\square$

\section{Applications}
As Theorem 1 shows, the tail of a martingale with bounded increments
decays as if the increments were Gaussian with variance proxy
$\sum c_i^2$. The notes use this to analyse polling-based load
balancing, where each routing decision is a bounded increment, and to
derive confidence bands for the empirical mean of dependent samples
collected by the telemetry pipeline.
\end{document}

